import { createFileRoute, Link, Outlet, redirect, useLocation, useNavigate } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { getAdminSession, signOutAdmin, type AdminSession } from "../lib/admin-auth";
import { listAdminCategories, removeAdminCategory, saveAdminCategory, type AdminCategory } from "../lib/admin-categories";
import { deleteAdminProduct, listAdminProducts, removeAdminProductImage, removeAdminProductVariant, saveAdminProduct, uploadAdminProductVideo, saveAdminProductVariant, updateAdminProductPrice, updateAdminProductVariantMaintenance, updateAdminProductPromotion, uploadAdminProductImage, type AdminProduct } from "../lib/admin-products";
import { listInventory, listInventoryMovements, listInventoryReservations, updateInventoryMinimum, type InventoryMovement, type InventoryReservation, type InventoryRow } from "../lib/admin-inventory";
import { getAdminOrder, listAdminOrders, updateAdminOrderStatus } from "../lib/orders";
import { supabase } from "../lib/supabase";
import { AdminSuppliers } from "../components/admin-suppliers";
import { deleteAdminBanner, getBannerRotationSeconds, listAdminBanners, saveAdminBanner, saveBannerRotationSeconds, type Banner } from "../lib/admin-banners";

export const Route = createFileRoute("/admin")({
  beforeLoad: async ({ location }) => {
    const session = await getAdminSession();
    if (!session && location.pathname !== "/admin/login") {
      throw redirect({ to: "/admin/login" });
    }
  },
  component: AdminRouteLayout,
});

function AdminRouteLayout() {
  const location = useLocation();
  const [session, setSession] = useState<AdminSession | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    void getAdminSession().then((currentSession) => {
      if (!active) return;
      setSession(currentSession);
      setLoading(false);
    });
    return () => {
      active = false;
    };
  }, []);

  if (location.pathname === "/admin/login") return <Outlet />;

  if (loading) {
    return <main className="flex min-h-screen items-center justify-center bg-background text-sm text-muted-foreground">Carregando painel...</main>;
  }

  if (!session) return null;

  return <AdminDashboard session={session} />;
}

function AdminDashboard({ session }: { session: AdminSession }) {
  const navigate = useNavigate();
  const [section, setSection] = useState("Visão geral");
  const [productArea, setProductArea] = useState<"Produtos" | "Categorias" | "Imagens" | "Variantes" | "Preços" | "Promoções">("Produtos");
  const [inventoryArea, setInventoryArea] = useState<"Estoque" | "Movimentações" | "Reservas" | "Alertas">("Estoque");
  const [appearanceArea, setAppearanceArea] = useState("Banners");

  function handleSectionChange(nextSection: string) {
    setSection(nextSection);
    if (nextSection === "Produtos") setProductArea("Produtos");
    if (nextSection === "Site e Conteúdo") setAppearanceArea("Banners");
  }

  async function handleSignOut() {
    await signOutAdmin();
    await navigate({ to: "/admin/login", replace: true });
  }

  const sections = ["Visão geral", "Site e Conteúdo", "Produtos", "Estoque", "Pedidos", "Fornecedores", "Logística", "Devoluções", "Financeiro", "Análises", "Clientes", "Configurações"];

  return <div className="min-h-screen bg-background text-foreground">
    <header className="border-b border-border bg-card">
      <div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-5 md:px-8">
        <Link to="/admin" className="text-sm font-semibold tracking-[0.16em]">LEH_CLOSETT <span className="text-primary">GLOW</span></Link>
        <div className="flex items-center gap-4 text-sm text-muted-foreground">
          <span className="hidden sm:inline">{session.email}</span>
          <button type="button" onClick={handleSignOut} className="rounded-lg border border-border px-3 py-2 transition hover:border-primary hover:text-primary">Sair</button>
        </div>
      </div>
    </header>
    <div className="mx-auto grid max-w-7xl gap-8 px-5 py-8 md:grid-cols-[14rem_1fr] md:px-8">
      <nav aria-label="Navegação administrativa" className="flex gap-2 overflow-x-auto md:flex-col md:overflow-visible">
        {sections.map((item) => <button key={item} type="button" onClick={() => handleSectionChange(item)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-left text-sm transition ${section === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-muted hover:text-foreground"}`}>{item}</button>)}
      </nav>
      <main key={section} className="min-w-0">
        <p className="mb-3 text-xs uppercase tracking-[0.24em] text-primary">Painel administrativo</p>
        <h1 className="text-4xl font-semibold tracking-tight md:text-5xl">{section}</h1>
        {section === "Visão geral" ? <OverviewDashboard /> : section === "Site e Conteúdo" ? <AppearanceArea area={appearanceArea} onAreaChange={setAppearanceArea} /> : section === "Produtos" ? <ProductsArea area={productArea} onAreaChange={setProductArea} /> : section === "Estoque" ? <InventoryArea area={inventoryArea} onAreaChange={setInventoryArea} /> : section === "Pedidos" ? <OrdersManager /> : section === "Fornecedores" ? <SuppliersManager /> : <section className="mt-8 rounded-xl border border-border bg-card p-8"><p className="text-muted-foreground">Selecione uma função no menu para visualizar e gerenciar esta área.</p></section>}
      </main>
    </div>
  </div>;
}

function OverviewDashboard() {
  const [period, setPeriod] = useState<"day" | "week" | "month">("week");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [now, setNow] = useState(new Date());
  const [orders, setOrders] = useState<any[]>([]);
  const [shipments, setShipments] = useState<any[]>([]);
  const [refunds, setRefunds] = useState<any[]>([]);

  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => window.clearInterval(timer); }, []);
  useEffect(() => { void (async () => {
    if (!supabase) { setError("Supabase não está configurado."); setLoading(false); return; }
    try {
      setLoading(true); setError("");
      const [orderResult, shipmentResult, refundResult] = await Promise.all([
        supabase.from("orders").select("id,total,created_at,status,payment_status,order_items(*)"),
        supabase.from("shipments").select("id,status,order_id"),
        supabase.from("refunds").select("amount,status,created_at")
      ]);
      if (orderResult.error) throw orderResult.error;
      if (shipmentResult.error) throw shipmentResult.error;
      if (refundResult.error) throw refundResult.error;
      setOrders(orderResult.data ?? []); setShipments(shipmentResult.data ?? []); setRefunds(refundResult.data ?? []);
    } catch (err) { setError(err instanceof Error ? err.message : "Não foi possível carregar os indicadores."); }
    finally { setLoading(false); }
  })(); }, []);

  const start = new Date();
  if (period === "day") start.setHours(0, 0, 0, 0);
  if (period === "week") { start.setDate(start.getDate() - 6); start.setHours(0, 0, 0, 0); }
  if (period === "month") { start.setDate(1); start.setHours(0, 0, 0, 0); }
  const paid = (order: any) => ["paid", "approved", "pago", "approved_payment"].includes(String(order.payment_status || "").toLowerCase());
  const periodOrders = orders.filter((order) => paid(order) && new Date(order.created_at) >= start);
  const sales = periodOrders.reduce((sum, order) => sum + Number(order.total || 0), 0);
  const totalSales = orders.filter(paid).reduce((sum, order) => sum + Number(order.total || 0), 0);
  const pending = orders.filter((order) => ["preparing", "processing", "paid", "pago"].includes(String(order.status || "").toLowerCase())).length;
  const inTransit = shipments.filter((shipment) => ["shipped", "in_transit", "em_transit", "em trânsito"].includes(String(shipment.status || "").toLowerCase())).length;
  const delivered = shipments.filter((shipment) => ["delivered", "entregue"].includes(String(shipment.status || "").toLowerCase())).length;
  const refundsTotal = refunds.filter((refund) => !refund.status || !["cancelled", "rejected"].includes(String(refund.status).toLowerCase())).reduce((sum, refund) => sum + Number(refund.amount || 0), 0);
  const buckets = period === "day" ? 6 : period === "week" ? 7 : 5;
  const chart = Array.from({ length: buckets }, (_, index) => { const date = new Date(start); if (period === "day") date.setHours(index * 4); else if (period === "week") date.setDate(start.getDate() + index); else date.setDate(1 + index * Math.max(1, Math.floor((new Date().getDate() - 1) / Math.max(1, buckets - 1)))); const next = new Date(date); if (period === "day") next.setHours(date.getHours() + 4); else if (period === "week") next.setDate(date.getDate() + 1); else next.setDate(date.getDate() + 7); return { label: period === "day" ? `${date.getHours()}h` : date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }), value: periodOrders.filter((order) => { const created = new Date(order.created_at); return created >= date && created < next; }).reduce((sum, order) => sum + Number(order.total || 0), 0) }; });
  const max = Math.max(...chart.map((item) => item.value), 1);
  const card = (label: string, value: string) => <article className="rounded-xl border border-border bg-card p-5"><p className="text-xs uppercase tracking-wider text-muted-foreground">{label}</p><p className="mt-3 text-2xl font-semibold tabular-nums">{loading ? "—" : value}</p></article>;
  return <div className="mt-8 space-y-6">{error && <p className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">{error}</p>}<div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Atualizado em {now.toLocaleString("pt-BR")}</p><div className="flex rounded-lg border border-border p-1">{(["day", "week", "month"] as const).map((item) => <button key={item} type="button" onClick={() => setPeriod(item)} className={`rounded-md px-3 py-1.5 text-sm ${period === item ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{item === "day" ? "Dia" : item === "week" ? "Semana" : "Mês"}</button>)}</div></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{card("Vendas no período", `R$ ${sales.toFixed(2)}`)}{card("Vendas totais", `R$ ${totalSales.toFixed(2)}`)}{card("Aguardando postagem", String(pending))}{card("Em trânsito", String(inTransit))}{card("Entregues", String(delivered))}{card("Total de devoluções", `R$ ${refundsTotal.toFixed(2)}`)}</div><section className="rounded-xl border border-border bg-card p-5"><div className="flex items-center justify-between"><div><h2 className="text-lg font-semibold">Vendas</h2><p className="text-sm text-muted-foreground">Pedidos pagos no período selecionado</p></div><strong className="text-xl">R$ {sales.toFixed(2)}</strong></div><div className="mt-6 flex h-48 items-end gap-2 border-b border-border">{chart.map((item) => <div key={item.label} className="flex flex-1 flex-col items-center gap-2"><div title={`R$ ${item.value.toFixed(2)}`} className="w-full rounded-t-md bg-primary transition-all" style={{ height: `${Math.max(item.value / max * 100, item.value ? 4 : 1)}%` }} /><span className="text-[11px] text-muted-foreground">{item.label}</span></div>)}</div></section></div>;
}

function AppearanceArea({ area, onAreaChange }: { area: string; onAreaChange: (area: string) => void }) {
  const areas = ["Banners", "Textos", "Seções", "Imagens", "Informações da loja", "Rodapé", "Redes sociais", "Políticas", "Configurações visuais"];
  return <div className="mt-8 space-y-6">
    <div className="rounded-xl border border-border bg-card p-5"><p className="text-sm text-muted-foreground">Central de edição da Home</p><p className="mt-1 text-sm text-muted-foreground">Edite o conteúdo publicado no site sem alterar outras áreas do painel.</p></div>
    <nav aria-label="Editor de aparência" className="flex gap-2 overflow-x-auto border-b border-border pb-px">{areas.map((item) => <button key={item} type="button" onClick={() => onAreaChange(item)} className={`whitespace-nowrap border-b-2 px-3 py-2 text-sm transition ${area === item ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{item}</button>)}</nav>
    {area === "Banners" ? <BannersEditor /> : area === "Textos" ? <TextAppearanceEditor /> : area === "Seções" ? <HomeSectionsEditor /> : area === "Informações da loja" ? <StorePresentationEditor /> : area === "Rodapé" ? <StorePresentationEditor mode="footer" /> : area === "Redes sociais" ? <StorePresentationEditor mode="social" /> : <section className="rounded-xl border border-border bg-card p-8"><h2 className="text-xl font-semibold">{area}</h2><p className="mt-2 text-sm text-muted-foreground">Esta área está preparada para receber os dados persistidos do Supabase quando o recurso correspondente estiver disponível.</p></section>}
  </div>;
}

type HomeSection = { id: string; title: string; type: "Categoria" | "Destaques" | "Mais vendidos" | "Produtos" | "Personalizada"; active: boolean; sort_order: number; category_id?: string; product_ids?: string[]; product_sort?: "recent" | "price_desc" | "price_asc" }; 

function HomeSectionsEditor() {
  const blank: Omit<HomeSection, "id"> = { title: "", type: "Destaques", active: true, sort_order: 0, category_id: "", product_ids: [], product_sort: "recent" }; 
  const [rows, setRows] = useState<HomeSection[]>([]); const [form, setForm] = useState(blank); const [editing, setEditing] = useState<string | undefined>(); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  const [categories, setCategories] = useState<AdminCategory[]>([]); const [products, setProducts] = useState<AdminProduct[]>([]);
  async function load() { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const value = Array.isArray(appearance.sections) ? appearance.sections : []; setRows(value.map((item, index) => ({ id: String((item as Record<string, unknown>).id ?? crypto.randomUUID()), title: String((item as Record<string, unknown>).title ?? ""), type: ((item as Record<string, unknown>).type ?? "Destaques") as HomeSection["type"], active: Boolean((item as Record<string, unknown>).active ?? true), sort_order: Number((item as Record<string, unknown>).sort_order ?? index), category_id: String((item as Record<string, unknown>).category_id ?? ""), product_ids: Array.isArray((item as Record<string, unknown>).product_ids) ? (item as Record<string, unknown>).product_ids as string[] : [], product_sort: ((item as Record<string, unknown>).product_sort ?? "recent") as HomeSection["product_sort"] })).sort((a, b) => a.sort_order - b.sort_order)); setLoading(false); }
  useEffect(() => { void load(); void (async () => { try { const [categoryRows, productRows] = await Promise.all([listAdminCategories(), listAdminProducts()]); setCategories(categoryRows.filter((item) => item.active)); setProducts(productRows.filter((item) => item.active)); } catch { setMessage("Não foi possível carregar categorias e produtos."); } })(); }, []);
  async function persist(next: HomeSection[]) { if (!supabase) return; const current = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (current.error) throw current.error; const appearance = current.data?.appearance && typeof current.data.appearance === "object" ? current.data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, sections: next } }); if (result.error) throw result.error; setRows(next); }
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!form.title.trim()) return; try { setSaving(true); setMessage(""); const next = editing ? rows.map((row) => row.id === editing ? { id: editing, ...form } : row) : [...rows, { id: crypto.randomUUID(), ...form, sort_order: rows.length }]; await persist(next); setForm(blank); setEditing(undefined); setMessage("Seções salvas no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  async function remove(id: string) { if (!window.confirm("Excluir esta seção da Home?")) return; try { await persist(rows.filter((row) => row.id !== id).map((row, index) => ({ ...row, sort_order: index }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível excluir."); } }
  async function move(id: string, direction: -1 | 1) { const index = rows.findIndex((row) => row.id === id); const target = index + direction; if (target < 0 || target >= rows.length) return; const next = [...rows]; [next[index], next[target]] = [next[target], next[index]]; try { await persist(next.map((row, order) => ({ ...row, sort_order: order }))); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível reordenar."); } }
  return <div className="space-y-6"><form onSubmit={submit} className="grid gap-4 rounded-xl border border-border bg-card p-5 md:grid-cols-2"><label className="text-sm">Título personalizado<input required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" /></label><label className="text-sm">Tipo<select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value as HomeSection["type"], category_id: "", product_ids: [] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3">{["Categoria", "Destaques", "Mais vendidos", "Produtos", "Personalizada"].map((type) => <option key={type}>{type}</option>)}</select></label>{form.type === "Categoria" && <label className="text-sm">Categoria<select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">Selecione uma categoria</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>}{(form.type === "Destaques" || form.type === "Produtos" || form.type === "Personalizada") && <div className="space-y-3 md:col-span-2"><div><p className="text-sm">Produtos selecionados <span className="text-muted-foreground">({form.product_ids.length}{form.type === "Destaques" ? "/10" : ""})</span></p><p className="mt-1 text-xs text-muted-foreground">A Home exibirá os produtos exatamente nesta ordem.</p>{form.type === "Personalizada" && <p className="mt-1 text-xs text-primary">Divisão personalizada da Home.</p>}</div><div className="space-y-2">{form.product_ids.length === 0 ? <p className="rounded-lg border border-dashed border-border p-4 text-sm text-muted-foreground">Nenhum produto selecionado.</p> : form.product_ids.map((productId, index) => { const product = products.find((item) => item.id === productId); return product ? <div key={product.id} className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2"><span className="truncate text-sm">{index + 1}. {product.name}</span><div className="flex shrink-0 gap-2 text-xs"><button type="button" disabled={index === 0} onClick={() => { const ids = [...form.product_ids]; [ids[index - 1], ids[index]] = [ids[index], ids[index - 1]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === form.product_ids.length - 1} onClick={() => { const ids = [...form.product_ids]; [ids[index], ids[index + 1]] = [ids[index + 1], ids[index]]; setForm({ ...form, product_ids: ids }); }} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => setForm({ ...form, product_ids: form.product_ids.filter((id) => id !== product.id) })} className="text-destructive">Remover</button></div></div> : null; })}</div><label className="block text-sm">Adicionar produto<select value="" disabled={form.type === "Destaques" && form.product_ids.length >= 10} onChange={(e) => { const id = e.target.value; if (id && !form.product_ids.includes(id) && (form.type !== "Destaques" || form.product_ids.length < 10)) setForm({ ...form, product_ids: [...form.product_ids, id] }); }} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="">{form.type === "Destaques" && form.product_ids.length >= 10 ? "Limite de 10 produtos atingido" : "Selecione um produto"}</option>{products.filter((product) => !form.product_ids.includes(product.id)).map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>{form.type === "Produtos" && <label className="block text-sm">Ordenação<select value={form.product_sort ?? "recent"} onChange={(e) => setForm({ ...form, product_sort: e.target.value as HomeSection["product_sort"] })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3"><option value="recent">Mais recentes</option><option value="price_desc">Maior preço</option><option value="price_asc">Menor preço</option></select></label>}</div>}<label className="flex items-center gap-2 pb-2 text-sm"><input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} />Ativa</label><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : editing ? "Atualizar" : "Criar seção"}</button></form>{message && <p className="rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}{loading ? <p className="text-sm text-muted-foreground">Carregando seções...</p> : rows.length === 0 ? <p className="rounded-xl border border-border bg-card p-8 text-sm text-muted-foreground">Nenhuma seção criada. A Home continuará com seu conteúdo padrão.</p> : <div className="space-y-3">{rows.map((row, index) => <article key={row.id} className="flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-card p-4"><div><h3 className="font-medium">{row.title}</h3><p className="text-sm text-muted-foreground">{row.type} · {row.active ? "Ativa" : "Inativa"} · {row.product_ids?.length ?? 0} produtos · posição {index + 1}</p></div><div className="flex gap-3 text-sm"><button type="button" disabled={index === 0} onClick={() => void move(row.id, -1)} className="text-primary disabled:opacity-40">Subir</button><button type="button" disabled={index === rows.length - 1} onClick={() => void move(row.id, 1)} className="text-primary disabled:opacity-40">Descer</button><button type="button" onClick={() => { setEditing(row.id); setForm({ title: row.title, type: row.type, active: row.active, sort_order: row.sort_order, category_id: row.category_id ?? "", product_ids: row.product_ids ?? [], product_sort: row.product_sort ?? "recent" }); }} className="text-primary">Editar</button><button type="button" onClick={() => void remove(row.id)} className="text-destructive">Excluir</button></div></article>)}</div>}</div>;
}

type StorePresentation = { storeName: string; storeDescription: string; instagram: string; linktree: string; whatsapp: string; whatsappFloating: string; footer: string };
type TextAppearance = { titleFont: string; titleSize: string; titleColor: string; phraseFont: string; phraseSize: string; phraseColor: string; textWidth: string; textFormat: "normal" | "uppercase" | "italic" };
const defaultTextAppearance: TextAppearance = { titleFont: "Playfair Display", titleSize: "clamp(3rem, 8vw, 7rem)", titleColor: "var(--foreground)", phraseFont: "Montserrat", phraseSize: "1rem", phraseColor: "var(--foreground)", textWidth: "32rem", textFormat: "normal" };

const defaultStorePresentation: StorePresentation = { storeName: "LEH_CLOSETT GLOW", storeDescription: "Moda para iluminar quem você é.", instagram: "", linktree: "", whatsapp: "", whatsappFloating: "", footer: "© 2025 LEH_CLOSETT GLOW. Todos os direitos reservados." };

function StorePresentationEditor({ mode = "all" }: { mode?: "all" | "footer" | "social" }) {
  const [form, setForm] = useState<StorePresentation>(defaultStorePresentation); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [message, setMessage] = useState("");
  useEffect(() => { void (async () => { if (!supabase) { setMessage("Supabase não está configurado."); setLoading(false); return; } const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) setMessage(error.message); const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; setForm({ ...defaultStorePresentation, ...(appearance.presentation as Partial<StorePresentation> | undefined) }); setLoading(false); })(); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!supabase) return; try { setSaving(true); const { data, error } = await supabase.from("store_settings").select("appearance").eq("id", "default").maybeSingle(); if (error) throw error; const appearance = data?.appearance && typeof data.appearance === "object" ? data.appearance as Record<string, unknown> : {}; const result = await supabase.from("store_settings").upsert({ id: "default", appearance: { ...appearance, presentation: form } }); if (result.error) throw result.error; setMessage("Apresentação salva no Supabase."); } catch (err) { setMessage(err instanceof Error ? err.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  const fields: Array<[keyof StorePresentation, string, string]> = mode === "footer" ? [["footer", "Texto do rodapé", ""]] : mode === "social" ? [["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"] , ["whatsapp", "WhatsApp", "https://wa.me/"] , ["whatsappFloating", "Número do botão flutuante", "5511999999999"]] : [["storeName", "Nome da loja", ""], ["storeDescription", "Descrição da loja", ""], ["instagram", "Instagram", "https://instagram.com/"], ["linktree", "Linktree", "https://linktr.ee/"], ["whatsapp", "WhatsApp", "https://wa.me/"], ["whatsappFloating", "Número do botão flutuante", "5511999999999"], ["footer", "Texto do rodapé", ""]];
  return <section className="rounded-xl border border-border bg-card p-5"><h2 className="text-xl font-semibold">Apresentação da loja</h2><p className="mt-1 text-sm text-muted-foreground">Esses dados são salvos na configuração real da loja.</p><form onSubmit={submit} className="mt-5 grid gap-4 md:grid-cols-2">{loading ? <p className="text-sm text-muted-foreground">Carregando configurações...</p> : <>{fields.map(([key, label, placeholder]) => <label key={key} className="text-sm">{label}{key === "storeDescription" || key === "footer" ? <textarea value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} rows={3} className="mt-2 w-full rounded-lg border border-input bg-background p-3" /> : <input value={form[key]} placeholder={placeholder} onChange={(event) => setForm({ ...form, [key]: event.target.value })} className="mt-2 h-10 w-full rounded-lg border border-input bg-background px-3" />}</label>)}<div className="md:col-span-2"><button disabled={saving} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">{saving ? "Salvando..." : "Salvar apresentação"}</button></div></>}</form>{message && <p className="mt-4 rounded-lg border border-border bg-muted p-3 text-sm">{message}</p>}</section>;
}

